{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C36"],
      "claim": "Aprepitant, which shares the same 3,5-bis(trifluoromethyl)phenyl ethoxy motif and a related N-heterocyclic scaffold, has an absolute oral bioavailability of 60-65% in humans, directly supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Flibanserin, another CF3-phenyl-containing heterocyclic drug, has an absolute oral bioavailability of about 46% in healthy volunteers, above the 20% threshold and supportive of adequate oral absorption for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Almorexant, a more distant CF3-phenyl amide analogue, has an absolute oral bioavailability of only about 11% in humans, indicating that some related structures can undergo extensive first-pass metabolism; however, its low structural transferability limits its weight against the aprepitant evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is most closely related to aprepitant, which has robust human absolute oral bioavailability around 60% despite high lipophilicity and low neutral fraction. The shared bis-CF3-phenyl ethoxy scaffold and N-heterocyclic core provide the strongest transferable evidence, supporting F >= 20%. More distant low-bioavailability analogues such as almorexant are less transferable and do not override this direct scaffold-level evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Metabolic stability and first-pass extraction of the spiro lactam-piperidine core are unknown.",
    "Solubility and dissolution behavior of the query are not experimentally characterized.",
    "Potential transporter-mediated efflux or absorption limitations are not assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

